.ds-method-details {margin-top: 28px;}
.ds-method-details > summary {cursor: pointer; list-style: none; width: fit-content;}
.ds-method-details > summary::-webkit-details-marker {display: none;}
.ds-method-details[open] > summary .ds-icon {transform: rotate(90deg);}
.ds-method-details ol {margin: 22px 0 0; padding-left: 24px;}
.ds-method-details li {padding-left: 8px;}
.ds-method-details li + li {margin-top: 20px;}
.ds-method-details li::marker {color: var(--color-green, #70c875); font-weight: 700;}
.ds-method-details h3 {font-size: 18px; line-height: 1.4; letter-spacing: -.01em;}
.ds-method-details li p {margin-top: 5px; font-size: 15px; line-height: 1.55; color: var(--color-on-dark-muted, #d2d5e7);}
.ds-method-details {margin-top:0;max-width:520px;}

